// Source-driven adaptations of Dime InsightsView custom horizontal pie/bar components.
import SwiftUI
struct DimeInsightsCategoryBars: View { let values:[DimeInsightsDataAdapter.CategoryTotal]; var body:some View { VStack(spacing:12){ForEach(values){value in VStack(alignment:.leading,spacing:5){HStack{Text(value.category?.name ?? String(localized:"Dime Insights Uncategorized")).font(.system(.body,design:.rounded).weight(.medium));Spacer();Text(value.amount,format:.currency(code:"EUR"))}.foregroundColor(Color.PrimaryText);GeometryReader{p in RoundedRectangle(cornerRadius:6.5).fill(Color(hex:value.category?.color ?? "#FFFFFF").opacity(0.35)).overlay(alignment:.leading){RoundedRectangle(cornerRadius:6.5).fill(Color(hex:value.category?.color ?? "#FFFFFF")).frame(width:p.size.width*value.percentage)}}.frame(height:12)} } } }
